const MAIN_UNITS=UNITS,MAIN_LESSONS=LESSONS,MAIN_WORDS=WORDS;
const ALL_LESSONS=[...MAIN_LESSONS,...JOB_COURSES.flatMap(c=>c.lessons)],ALL_WORDS=ALL_LESSONS.flatMap(l=>l.words);
for(const c of JOB_COURSES)Object.assign(ASSESSMENT_OVERRIDES,c.overrides);
let activeCourseId='main';
function activeJob(){return JOB_COURSES.find(c=>c.id===activeCourseId)}
function courseTitle(){const c=activeJob();return c?arabicTitle171(c.title,'track-'+c.id):'رحلة التعلّم A1–C2'}
function applyCourse(id){const c=JOB_COURSES.find(c=>c.id===id);activeCourseId=c?.id||'main';UNITS=c?.units||MAIN_UNITS;LESSONS=c?.lessons||MAIN_LESSONS;WORDS=c?c.lessons.flatMap(l=>l.words):MAIN_WORDS;}
function chooseCourse(id){if(id===activeCourseId)return;state.sessions=state.sessions||{};state.sessions[activeCourseId]=state.session;applyCourse(id);state.session=state.sessions[activeCourseId]||null;view={};cardRun=null;storyRun=null;placementRun=null;save(false);}
function coursesPage(){return layout(Arabic169.template("6a309b2d5d345a32")`<div class="reading"><h1>اختار مسارك</h1><p>رحلة اللغة والأقسام المهنية مستقلة عن بعض. كل مسار ليه دروسه وتقدمه ومراجعته.</p><section class="card"><h2>رحلة التعلّم A1–C2</h2><p>ابدأ من الصفر أو حدّد مستواك. الأقسام المهنية مش شرط لدخول أي مستوى.</p><button class="btn" data-action="course" data-id="main">افتح رحلة التعلّم</button></section>${JOB_COURSES.map(c=>Arabic169.template("ac1bd2ad833eaa24")`<section class="card"><h2>${esc(arabicTitle171(c.title,'track-'+c.id))}</h2><p>${ArabicCount169.selected(c.units.length,"unit",c.units.length)} وحدات · ${ArabicCount169.selected(c.lessons.length,"lesson",c.lessons.length)} درس قصير · مفتوح من غير اختبار مستوى.</p><p>${ArabicCount169.format(c.lessons.filter(l=>state.completed[l.id]).length)} من ${ArabicCount169.selected(c.lessons.length,"lesson",c.lessons.length)} درس مكتمل</p><button class="btn secondary" data-action="course" data-id="${c.id}">افتح القسم</button></section>`).join('')}</div>`)}
function jobProgress(){const n=LESSONS.filter(l=>state.completed[l.id]).length;return layout(Arabic169.template("86a46edc373ca384")`<div class="reading"><h1>تقدّمك في ${esc(courseTitle())}</h1><section class="card"><h2>${ArabicCount169.format(n)} من ${ArabicCount169.selected(LESSONS.length,"lesson",LESSONS.length)} درس</h2>${bar(n/LESSONS.length*100)}<p>${ArabicCount169.format(WORDS.filter(w=>state.words[w.id]).length)} من ${ArabicCount169.selected(WORDS.length,"expression",WORDS.length)} تعبير اتدرّبت عليه.</p><p>التقدم هنا مستقل عن رحلة A1–C2. خطوات تعلّمك اليومية بتتجمّع من التدريب الحقيقي في كل المسارات.</p></section><a class="btn" href="#path">ارجع للوحدات</a><a class="btn secondary" href="#courses">اختار مسار تاني</a></div>`)}
function startMock(){const learned=LESSONS.filter(l=>state.completed[l.id]),units=shuffled([...new Set(learned.map(l=>l.unit))]);if(units.length<2)return toast('اتدرّب على دروس من وحدتين الأول، عشان المقابلة تراجع حاجة اتعلّمتها.');view.mock={items:units.slice(0,8).map(ui=>shuffled(learned.filter(l=>l.unit===ui))[0]).map(l=>({id:l.id,source:l.dialog[0],meaning:l.dialog[2],responseMeaning:l.dialog[3],answer:l.dialog[1],speaker:l.dialogSpeakers[0],options:shuffled([l.dialog[1],...ASSESSMENT_OVERRIDES[l.id].replyAlternatives.map(a=>a.es)])})),at:0,score:0,feedback:null};location.hash='mock';render();}
function mockPage(){const r=view.mock;if(!r)return layout(Arabic169.template("7673b79cbc6c1454")`<div class="reading"><h1>مقابلة مختلطة قصيرة</h1><p>لحد ثمانية أسئلة من وحدات اتدرّبت عليها. كمّل دروس من وحدتين على الأقل، وبعدين اختر الرد بالمعنى المطلوب؛ دي مراجعة لغة، مش تقييم لشخصيتك أو فرصك في الشغل.</p><p>الأمثلة للتدريب. في المقابلة الحقيقية استخدم خبرتك ومعلوماتك الحقيقية.</p><button class="btn" data-action="mock-start">ابدأ المراجعة</button></div>`);if(r.at===r.items.length)return layout(Arabic169.template("2fb0531322cf744c")`<div class="reading"><h1>خلصت المقابلة التدريبية</h1><p>${r.score} من ${r.items.length} من أول محاولة.</p><p>دي نتيجة تدريب على العبارات، مش اختبار توظيف أو تحديد مستوى.</p><button class="btn" data-action="mock-start">جولة جديدة</button><a class="btn secondary" href="#home">ارجع للقسم</a></div>`);const q=r.items[r.at];return layout(Arabic169.template("2e92a2d9742a1d6d")`<div class="reading"><div class="eyebrow">مقابلة تدريبية · ${r.at+1} من ${r.items.length}</div><h1>اختار الرد اللي معناه المطلوب</h1>${dialogLine(q.source,q.meaning,q.speaker)}<p>المعنى المطلوب: ${arabicLearning169(q.responseMeaning)}</p><div class="options">${q.options.map((o,i)=>`<button class="tile" data-action="mock-answer" data-index="${i}" ${r.feedback!==null?'disabled':''}><span class="es" lang="es" dir="ltr">${esc(o)}</span></button>`).join('')}</div>${r.feedback!==null?Arabic169.template("9b9f544622f9fc3f")`<p class="feedback ${r.feedback?'good':'bad'}">${r.feedback?'صح.':'الرد المطلوب: '+esc(q.answer)}</p><button class="btn" data-action="mock-next">كمّل</button>`:''}</div>`)}
